def move_to_the_queue(apps, schema_editor):
    """Commands waiting before the queue existed are in no queue: fail them.
    Runtimes started before it read no queue: a new config version makes the
    controller replace each one between turns."""
    AgentCommand = apps.get_model("chat", "AgentCommand")
    Message = apps.get_model("chat", "Message")
    waiting = AgentCommand.objects.filter(status__in=["queued", "dispatching"])
    Message.objects.filter(
        command__in=waiting, role="assistant", status__in=["queued", "stopping"]
    ).update(
        status="failed",
        failure={
            "code": "REPLY_INTERRUPTED",
            "message": "执行中断，无法确认结果，未自动重试。",
        },
    )
    waiting.update(status="failed", error_code="REPLY_INTERRUPTED")
    Agent = apps.get_model("chat", "Agent")
    Agent.objects.update(config_version=F("config_version") + 1)


